@import "theme";
@import url('./default.scss');
@import url('./fonts.scss');
@import url('./languages.scss');

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  scroll-behavior: smooth;
}

body {
  height: 100%;
  -webkit-tap-highlight-color: rgba(0, 0, 0, 0);
  font-family: "Exo2", sans-serif;
  overflow-x: hidden;
}


.wrapper {
  max-width: 1600px;
  margin-left: auto;
  margin-right: auto;

  @media screen and (max-width: $desktop) {
    max-width: calc($desktop - 60px);
    padding-left: 30px;
    padding-right: 30px;
  }

  @media screen and (max-width: $notebook) {
    max-width: calc($notebook - 60px);
    padding-left: 30px;
    padding-right: 30px;
  }


  @media screen and (max-width: $mainbreak) {
    max-width: $mainbreak;
    padding-left: 30px;
    padding-right: 30px;
  }

  @media screen and (max-width: $tablet) {
    max-width: $tablet;
    padding-left: 24px;
    padding-right: 24px;
  }

  @media screen and (max-width: $mobile) {
    padding-left: 16px;
    padding-right: 16px;
  }
}

.body-scroll-disable {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

