:root {
  --page--side-padding: 3rem;
  --scrollbar-track-color: #ffffff;
  --scrollbar-thumb-color: #0691ff;
  --scrollbar-thumb-hover-color: #3fa8ff;
  --twinkle-duration: 4s;
  --border-radius: 8px;
}

@media screen and (max-width: 1440px) {
  :root {
    --page--side-padding: 2rem;
  }
}
@media screen and (max-width: 960px) {
  :root {
    --page--side-padding: 1rem;
  }
}
html {
  scroll-behavior: smooth;
  padding: 0;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

body,
h1,
h2,
h3,
h4,
p,
ul,
ol,
li {
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
}

input {
  border-radius: 8px;
  background-color: #fff;
}

label {
  display: block;
}

